from pathlib import Path
import hashlib,base64,gzip,json
root=Path('tach-xep-pdf-v2.3.2')
p=root/'TachXepTrangPDF.cs'
raw=p.read_bytes()
expected_base='ff4279b4dfa8a8972d443ccb200e7e0f1da5602c2a4801dc6696e044fd5caae8'
if hashlib.sha256(raw).hexdigest()!=expected_base:
    raise SystemExit('unexpected v2.4.4 reconstructed source before v2.4.5 patch')
lines=raw.decode('utf-8-sig').replace('\r\n','\n').splitlines(True)
ops=json.loads(gzip.decompress(base64.b64decode('')).decode('utf-8'))
offset=0
for tag,i1,i2,repl in ops:
    a=i1+offset; b=i2+offset
    lines[a:b]=repl
    offset += len(repl)-(i2-i1)
out=''.join(lines).encode('utf-8-sig')
expected_final='7051ace6f2d9de56553e268d2e8bf6a88bcdc67a15a8610e2c04f215f83398d6'
actual=hashlib.sha256(out).hexdigest()
if actual!=expected_final:
    raise SystemExit('v2.4.5 source patch checksum mismatch actual='+actual)
p.write_bytes(out)
launcher=root/'launcher.cpp'
ls=launcher.read_text(encoding='utf-8-sig')
ls2=ls.replace('2.4.4','2.4.5')
if ls2==ls: raise SystemExit('launcher v2.4.4 marker missing')
launcher.write_text(ls2,encoding='utf-8-sig')
print('PATCH_V245_PAGE_CACHE_COMPACT_UI_OK source_sha256='+actual)
